-- ✅ HOW TO ENFORCE ATOMICITY IN SQL
BEGIN TRANSACTION;

BEGIN TRY
    -- Step 1: Subtract from Alice
    UPDATE Accounts SET Balance = Balance - 100 WHERE Name = 'Alice';

    -- Step 2: Add to Bob
    UPDATE Accounts SET Balance = Balance + 100 WHERE Name = 'Bob';

    -- If both steps succeed, we permanently save it (Durability)
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    -- If ANY step fails, we undo everything! (Atomicity)
    ROLLBACK TRANSACTION;
END CATCH

// ❌ INLINE SQL (The old, dangerous way)
// Vulnerable to SQL Injection!
string sql = "SELECT * FROM Users WHERE Name = '" + userName + "'";
dbCommand.CommandText = sql;

// ✅ INLINE SQL (The modern Entity Framework way)
// EF Core safely generates parameterized SQL for you.
var users = dbContext.Users.Where(u => u.Name == userName).ToList();


// ⚙️ CALLING A STORED PROCEDURE
// The actual SQL logic is hidden inside the database.
var users = dbContext.Users.FromSqlRaw("EXECUTE dbo.GetActiveUsers").ToList();

-- ✅ SQL (Rigid Schema)
-- You MUST define the exact data types beforehand.
CREATE TABLE Users (
    Id INT PRIMARY KEY,
    Name VARCHAR(100) NOT NULL,
    Age INT
);


