-- ❌ HOW A DEADLOCK IS CREATED

-- User 1 runs this script:
BEGIN TRANSACTION;
UPDATE TableA SET Value = 1; -- Gets Lock on A
WAITFOR DELAY '00:00:05';
UPDATE TableB SET Value = 1; -- Needs Lock on B (WAITS)
COMMIT;

-- User 2 runs this script at the exact same time:
BEGIN TRANSACTION;
UPDATE TableB SET Value = 1; -- Gets Lock on B
WAITFOR DELAY '00:00:05';
UPDATE TableA SET Value = 1; -- Needs Lock on A (WAITS FOR USER 1)
COMMIT;

-- RESULT: SQL Server kills one of them with Error 1205.
